from pathlib import Path
from datetime import datetime, timedelta, timezone
import re, uuid

files = {
    'alice': Path('/app/alice_calendar.ics'),
    'bob': Path('/app/bob_calendar.ics'),
    'carol': Path('/app/carol_calendar.ics'),
}

DT_RE = re.compile(r'^(DTSTART|DTEND)(?:[^:;]*?)\s*:(.+)$', re.IGNORECASE)


def parse_ics_dt(s: str) -> datetime:
    s = s.strip()
    # Support YYYYMMDDTHHMMSSZ or floating local times (assumed UTC per prompt)
    if s.endswith('Z'):
        return datetime.strptime(s, '%Y%m%dT%H%M%SZ').replace(tzinfo=timezone.utc)
    if 'T' in s:
        return datetime.strptime(s, '%Y%m%dT%H%M%S').replace(tzinfo=timezone.utc)
    # all-day dates not expected for meeting conflicts; treat as midnight UTC
    return datetime.strptime(s, '%Y%m%d').replace(tzinfo=timezone.utc)


def unfold_lines(text: str):
    out = []
    for line in text.splitlines():
        if line.startswith((' ', '\t')) and out:
            out[-1] += line[1:]
        else:
            out.append(line.rstrip('\r'))
    return out


def extract_events(path: Path):
    text = path.read_text()
    lines = unfold_lines(text)
    events = []
    in_event = False
    cur = {}
    for line in lines:
        if line == 'BEGIN:VEVENT':
            in_event = True
            cur = {}
            continue
        if line == 'END:VEVENT':
            if 'DTSTART' in cur and 'DTEND' in cur:
                events.append((cur['DTSTART'], cur['DTEND']))
            in_event = False
            cur = {}
            continue
        if in_event:
            m = DT_RE.match(line)
            if m:
                key, val = m.group(1).upper(), m.group(2)
                cur[key] = parse_ics_dt(val)
    return events


def weekday_name(dt):
    return ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][dt.weekday()]

busy = {name: extract_events(path) for name, path in files.items()}

# Extend Carol's busy intervals by 15 minutes after meetings ending at 16:45 or later.
carol_busy = []
for s, e in busy['carol']:
    if e.hour > 16 or (e.hour == 16 and e.minute >= 45):
        e = e + timedelta(minutes=15)
    carol_busy.append((s, e))
busy['carol'] = carol_busy

