end_search = datetime(2024, 1, 19, 17, 0, tzinfo=timezone.utc)  # latest possible 1h start within Carol's 5pm cap
meeting_len = timedelta(hours=1)

# Hard availability constraints

def allowed_by_person(person, start, end):
    wd = start.weekday()  # 0=Mon ... 4=Fri
    if wd > 4:
        return False
    # business hours local=UTC
    if start.hour < 9 or end.hour > 18 or (end.hour == 18 and end.minute > 0):
        return False
    if person == 'alice':
        return start.hour >= 9 and end.hour <= 14
    if person == 'bob':
        if start.hour < 10:
            return False
        if wd in (1, 3) and end > datetime(start.year, start.month, start.day, 16, 30, tzinfo=timezone.utc):
            return False
        return True
    if person == 'carol':
        if start.hour < 9 or end > datetime(start.year, start.month, start.day, 17, 0, tzinfo=timezone.utc):
            return False
        if start < datetime(start.year, start.month, start.day, 12, 0, tzinfo=timezone.utc) and end > datetime(start.year, start.month, start.day, 12, 0, tzinfo=timezone.utc):
            # overlap lunch break 12:00-12:30
            if start < datetime(start.year, start.month, start.day, 12, 30, tzinfo=timezone.utc):
